import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";

export type NonprofitCause = {
  /** The URL to the banner of the cause. */
  bannerUrl: string;
  /** The description of the cause. */
  description: string;
  /** The unique identifier of the cause. This value is generated by Adyen. */
  id?: string;
  /**
   * The locales that the cause supports, in [IETF BCP
   * 47](https://en.wikipedia.org/wiki/IETF_language_tag) format.
   */
  locales: string[];
  /** The name of the cause. */
  name: string;
};

export const nonprofitCauseSchema: Schema<NonprofitCause> = s.object<NonprofitCause>({
  bannerUrl: s.string(),
  description: s.string(),
  id: s.optional(s.string()),
  locales: s.array(s.string()),
  name: s.string(),
});
